import csv
import io
import re


_NUMBER = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")


def parse_csv(raw_csv: str):
    expected_width = 9
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    directive = re.match(r"sep=,(?:\r\n|\n|\r|$)", raw_csv, re.IGNORECASE)
    if directive:
        raw_csv = raw_csv[directive.end():]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
    ))

    def number_count(row):
        return sum(_NUMBER.fullmatch(value.strip()) is not None for value in row)

    columns = []
    first = next((i for i, row in enumerate(records) if any(cell.strip() for cell in row)), None)
    if first is not None:
        candidate = records[first]
        labels = sum(
            any(char.isalpha() for char in cell)
            and _NUMBER.fullmatch(cell.strip()) is None
            for cell in candidate
        )
        if len(candidate) == expected_width and labels > expected_width // 2:
            for i in range(first + 1, len(records)):
                following = records[i]
                if not any(cell.strip() for cell in following):
                    continue
                if number_count(following) > expected_width // 2:
                    columns = records.pop(first)
                break

    width = max(expected_width, len(columns), max(map(len, records), default=0))
    used = set(columns)
    while len(columns) < width:
        base = f"column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used.add(name)

    rows = [row + [""] * (width - len(row)) for row in records]
    return {"columns": columns, "rows": rows}
